:root {
  --ink: #17352d;
  --court: #2f805f;
  --paper: #fffdf5;
  --line: #b8d8c7;
  --ball: #e8ed4a;
}

.court-pass {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--court);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h1 {
  margin: 5px 0 0;
  font-size: 21px;
  line-height: 1.1;
}

.details {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 0;
  font-size: 14px;
}

.details strong {
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--ball);
  font-size: 12px;
}

button {
  width: 100%;
  padding: 9px 12px;
  border: 0;
  border-radius: 7px;
  background: var(--court);
  color: var(--paper);
  font-size: 14px;
  font-weight: 800;
}
